package main

import (
	"strings"
	"testing"

	"tradeloom/internal/service"
)

func TestGenerate(t *testing.T) {
	out := Generate(service.EventCatalogue())
	for _, want := range []string{
		"// Code generated by internal/app/eventsgen. DO NOT EDIT.",
		"export interface service_SessionStatus {",
		"  credentials: kite_CredentialsInfo;",
		"  expiresAtMs: number;",
		"export interface kite_Order {",
		"  order_id: string;",
		"  order_timestamp: string;",
		"  meta: Record<string, unknown> | null;",
		"export interface service_MarketStatus {",
		"  atMs: number;",
		`  "session.state": service_SessionStatus;`,
		`  "tick.batch": Array<service_TickDTO> | null;`,
		`  "feed.state": service_FeedStateDTO;`,
		`  "clock.offset": service_OffsetDTO;`,
		`  "limits.usage": service_UsageDTO;`,
		`  "backfill.progress": Array<service_BackfillProgressDTO> | null;`,
		"  classes: Array<service_ClassUsageDTO> | null;",
		"  etaMs: number;",
		"  nextRetryMs: number;",
		`  "orders.changed": orders_BookSnapshot;`,
		`  "order.update": kite_Order;`,
		`  "market.status": service_MarketStatus;`,
		`  "job.progress": service_JobProgress;`,
		`  "app.navigate": service_Navigate;`,
		`  sessionState: "session.state",`,
		`  appNavigate: "app.navigate",`,
		"export type EventName = keyof EventPayloads;",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("missing %q", want)
		}
	}
	for _, bad := range []string{"nextRetry: string", "updatedAt: string", "etaNs", "backoffUntil: string"} {
		if strings.Contains(out, bad) {
			t.Errorf("time-typed field %q in payloads", bad)
		}
	}
	if strings.Contains(out, "v4_Order") {
		t.Error("gokiteconnect types must be namespaced kite_, not v4_")
	}
}

// The generated file is committed, so the output must not depend on map iteration or run order.
func TestGenerate_Deterministic(t *testing.T) {
	first := Generate(service.EventCatalogue())
	for i := 0; i < 20; i++ {
		if got := Generate(service.EventCatalogue()); got != first {
			t.Fatalf("run %d differs", i)
		}
	}
}
